function applyWorkspace(data){const localDraft=current()?.draft,localNote=shared?current()?.noteDraft:'';shared=true;sharedIdentity=data.identity;sharedStaff=data.staff||[];serverOffset=(data.serverNow||Date.now())-Date.now();threads=data.threads;lessons=data.learning||[];savedReplies=data.replies||[];if(draftDirty&&current())current().draft=localDraft||'';if(current()&&localNote)current().noteDraft=localNote;$('agent').value=sharedIdentity;$('agent').disabled=false;$('owner').innerHTML='<option value="">Unassigned</option>'+sharedStaff.map(r=>'<option value="'+esc(r.email)+'">'+esc(r.name)+'</option>').join('');$('shared-status').textContent='Shared test inbox · working as '+sharedIdentity;$('connect-shared').hidden=true;$('export-shared').hidden=false;$('reset').disabled=true;['take-over','return-queue','refresh-shared'].forEach(id=>$(id).hidden=false);document.querySelector('#saved-section > p').textContent='Reusable drafts shared with signed-in staff. Review before use.';document.querySelector('.sample-banner span').textContent='Shared fictional conversations. Nothing is sent to WhatsApp or written into CRM.';render();renderSaved();renderLessons();renderPresence();}
function queueShared(action,threadId=current().id){const initiatingProfile=sharedIdentity;sharedQueue=sharedQueue.catch(()=>{}).then(async()=>{const thread=threads.find(t=>t.id===threadId);if(!thread)throw Error('Thread no longer exists');const type=action.type,change={...action};delete change.type;const data=await workspaceRequest({threadId,revision:thread.revision,action:type,change},initiatingProfile);if(type==='draft'&&current().id===threadId&&current().draft===action.text)draftDirty=false;if(['note','edit_note'].includes(type)){current().noteDraft='';cancelNoteEdit();}if(type==='booking')bookingEdits.delete(threadId);applyWorkspace(data);if(type==='incoming'&&current().id===threadId){$('sample-incoming').value='';$('sample-incoming-form').closest('details').open=false;if($('auto-draft').checked){$('suggest-source').value='';document.querySelector('.suggest-tools').open=true;$('suggest-reply').click();}}notice('Shared '+type+' saved · no WhatsApp message sent.');}).catch(error=>{notice(error.message+' Your unsaved text remains on this device; refresh and review before retrying.');});return sharedQueue;}
