$('backup-download').onclick=async()=>{const button=$('backup-download');button.disabled=true;try{if(!shared)throw Error('Open the shared test inbox first.');const password=$('backup-password').value;if(password.length<12)throw Error('Use a passphrase of at least 12 characters.');const response=await fetch('/api/whatsapp/workspace?export=1',{cache:'no-store',headers:{'X-MBW-Staff-Profile':agent()}});if(!response.ok)throw Error('Backup unavailable');const snapshot=await response.json(),backup=await encryptBackup(await packBackup(snapshot),password),url=URL.createObjectURL(new Blob([JSON.stringify(backup)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='mbw-test-inbox-encrypted-'+new Date().toISOString().replaceAll(':','-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('backup-state').textContent='Encrypted backup downloaded. Store it separately from the shared database, then validate the file below.';}catch(error){$('backup-state').textContent=error.message;}finally{button.disabled=false;$('backup-password').value='';}};
$('backup-file').onchange=async()=>{const file=$('backup-file').files[0];$('backup-preview').replaceChildren();if(!file)return;try{if(file.size>20*1024*1024)throw Error('Backup is larger than the 20 MB test limit.');let value=JSON.parse(await file.text());if(value.format==='mbw-whatsapp-encrypted-backup')value=await decryptBackup(value,$('backup-password').value);const {snapshot,summary}=await unpackBackup(value);$('backup-state').textContent='Backup verified · isolated recovery preview · shared inbox unchanged.';$('backup-preview').innerHTML='<p>'+esc(summary.conversations)+' conversations · '+esc(summary.messages)+' messages · '+esc(summary.notes)+' notes · '+esc(summary.savedReplies)+' saved replies · '+esc(summary.historyVersions)+' lesson versions · '+esc(summary.auditEvents)+' audit events</p><p class="small">Exported '+esc(summary.exportedAt)+'</p>'+snapshot.threads.map(t=>'<details><summary>'+esc(t.name)+'</summary><p>'+esc(t.nextAction||'No next action')+'</p>'+t.messages.map(m=>'<p><strong>'+esc(m.direction==='in'?'Guest':m.actor||'Staff')+':</strong> '+esc(m.text)+'</p>').join('')+'</details>').join('');}catch(error){$('backup-state').textContent=error.message;}finally{$('backup-password').value='';$('backup-file').value='';}};
